window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["aiops-08-observability-br-study-guide"]={"html":"\r\n\r\n\r\n\r\n\r\nObservability Study Guide — Loki · Prometheus · Grafana — By Nabawy — SIGNAL Theme\r\n\r\n\r\n\r\n\r\n<div class=\"sheet cover\">\r\n<div class=\"band\">\r\n<div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div><div class=\"bar\"></div>\r\n</div>\r\n<div class=\"ckick\">SIGNAL SERIES · OBSERVABILITY ON KUBERNETES</div>\r\n<h1 id=\"observabilitystudy-guide\">Observability<br />Study Guide</h1>\r\n<div class=\"sub\">The complete merged edition — <b>Loki + Promtail</b> for logs, <b>Prometheus + exporters</b> for metrics, and <b>Grafana</b> for visualization — deployed on <b>Minikube with Helm</b>. Fundamentals → architecture → deployment → LogQL/PromQL → app integration → troubleshooting → mental model → terms glossary → interview prep. One concrete lab: a Minikube cluster, a dedicated <code>observability</code> namespace, two Helm charts.</div>\r\n<div class=\"byline\">By <span class=\"sig\">Nabawy</span><small>AUTHOR &amp; COMPILER</small></div>\r\n<div class=\"vols\">\r\n<div class=\"volcard on\">MERGED EDITION<small>Study + Deployment · A4</small></div>\r\n<div class=\"volcard\">Loki<small>+ Promtail 📜</small></div>\r\n<div class=\"volcard\">Prometheus<small>+ Exporters 📈</small></div>\r\n<div class=\"volcard\">Grafana<small>Dashboards 📊</small></div>\r\n<div class=\"volcard\">Minikube<small>+ Helm ⎈</small></div>\r\n</div>\r\n<div class=\"cver\">LOGS · METRICS · TRACES · VISUALIZATION — BY NABAWY · verified 2026-09-18</div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Contents</div><h1 id=\"table-of-contents\">📖 Table of Contents</h1></div><span class=\"hmeta\">14 parts · 26 pages</span></div></div>\r\n<div class=\"tocgrid\">\r\n<div>\r\n<a href=\"#summary\"><span class=\"tnum\">🗺️</span><span>The Map — Executive Summary</span><span class=\"dots\"></span><span class=\"tp\">3</span></a>\r\n<a href=\"#ch-01\"><span class=\"tnum\">01</span><span>What is Observability? — Four Pillars</span><span class=\"dots\"></span><span class=\"tp\">4</span></a>\r\n<a href=\"#ch-02\"><span class=\"tnum\">02</span><span>Logs vs Metrics vs Traces</span><span class=\"dots\"></span><span class=\"tp\">5</span></a>\r\n<a href=\"#ch-02b\"><span class=\"tnum\">02·b</span><span>The Core Stack at a Glance</span><span class=\"dots\"></span><span class=\"tp\">6</span></a>\r\n<a href=\"#ch-03\"><span class=\"tnum\">03</span><span>Logs 1/3 — Why Loki?</span><span class=\"dots\"></span><span class=\"tp\">7</span></a>\r\n<a href=\"#ch-03b\"><span class=\"tnum\">03·b</span><span>Logs 2/3 — Loki Architecture</span><span class=\"dots\"></span><span class=\"tp\">8</span></a>\r\n<a href=\"#ch-03c\"><span class=\"tnum\">03·c</span><span>Logs 3/3 — Promtail Workflow</span><span class=\"dots\"></span><span class=\"tp\">9</span></a>\r\n<a href=\"#ch-04\"><span class=\"tnum\">04</span><span>Metrics 1/2 — Prometheus Fundamentals</span><span class=\"dots\"></span><span class=\"tp\">10</span></a>\r\n<a href=\"#ch-04b\"><span class=\"tnum\">04·b</span><span>Metrics 2/2 — The Metric Sources</span><span class=\"dots\"></span><span class=\"tp\">11</span></a>\r\n<a href=\"#ch-05\"><span class=\"tnum\">05</span><span>Traces — Journey of a Request</span><span class=\"dots\"></span><span class=\"tp\">12</span></a>\r\n<a href=\"#ch-06\"><span class=\"tnum\">06</span><span>Visualization — Grafana</span><span class=\"dots\"></span><span class=\"tp\">13</span></a>\r\n<a href=\"#ch-07\"><span class=\"tnum\">07</span><span>How It All Fits Together in K8s</span><span class=\"dots\"></span><span class=\"tp\">14</span></a>\r\n</div>\r\n<div>\r\n<a href=\"#ch-08\"><span class=\"tnum\">08</span><span>Deployment 1/2 — Helm + prometheus-stack</span><span class=\"dots\"></span><span class=\"tp\">15</span></a>\r\n<a href=\"#ch-08b\"><span class=\"tnum\">08·b</span><span>Deployment 2/2 — loki-stack + The Gotcha</span><span class=\"dots\"></span><span class=\"tp\">16</span></a>\r\n<a href=\"#ch-09\"><span class=\"tnum\">09</span><span>Querying 1/2 — LogQL</span><span class=\"dots\"></span><span class=\"tp\">17</span></a>\r\n<a href=\"#ch-09b\"><span class=\"tnum\">09·b</span><span>Querying 2/2 — PromQL</span><span class=\"dots\"></span><span class=\"tp\">18</span></a>\r\n<a href=\"#ch-10\"><span class=\"tnum\">10</span><span>Application Integration</span><span class=\"dots\"></span><span class=\"tp\">19</span></a>\r\n<a href=\"#ch-11\"><span class=\"tnum\">11</span><span>Troubleshooting Playbook 1/2</span><span class=\"dots\"></span><span class=\"tp\">20</span></a>\r\n<a href=\"#ch-11b\"><span class=\"tnum\">11·b</span><span>Troubleshooting 2/2 + Cleanup</span><span class=\"dots\"></span><span class=\"tp\">21</span></a>\r\n<a href=\"#ch-13\"><span class=\"tnum\">13</span><span>The Mental Model — Architecture</span><span class=\"dots\"></span><span class=\"tp\">22</span></a>\r\n<a href=\"#ch-13b\"><span class=\"tnum\">13·b</span><span>Quick Revision — Terms Glossary</span><span class=\"dots\"></span><span class=\"tp\">23</span></a>\r\n<a href=\"#ch-14\"><span class=\"tnum\">14</span><span>Interview Prep — 14 Concepts</span><span class=\"dots\"></span><span class=\"tp\">24</span></a>\r\n<a href=\"#ch-14b\"><span class=\"tnum\">14·b</span><span>Command Cheat Sheet</span><span class=\"dots\"></span><span class=\"tp\">25</span></a>\r\n<a href=\"#ch-14c\"><span class=\"tnum\">14·c</span><span>Self-Quiz + Answer Key</span><span class=\"dots\"></span><span class=\"tp\">26</span></a>\r\n</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [Status Color Legend]<span class=\"hst\">theme guide</span></div>\r\n<div class=\"lgd\">\r\n<div><span class=\"dot8\"></span> TEAL — headings &amp; series structure</div>\r\n<div><span class=\"dot8\"></span> INDIGO — core concepts (KEY IDEA)</div>\r\n<div><span class=\"dot8\"></span> GREEN — confirmations &amp; proofs</div>\r\n<div><span class=\"dot8\"></span> AMBER — cautions &amp; notes</div>\r\n<div><span class=\"dot8\"></span> RED — symptoms &amp; failures</div>\r\n</div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE</span><b>How to use this book:</b> 14 connected parts merging the study guide and the deployment guide into one journey — defining Observability, the three signal types, Loki/Promtail architecture, Prometheus/exporters, Grafana, the full Minikube + Helm deployment, LogQL/PromQL querying, app integration, a troubleshooting playbook, a terms glossary, and interview prep. Every term stays in English exactly as used in the industry.</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span><b>The lab this book documents:</b> one Minikube cluster · one dedicated <code>observability</code> namespace · two Helm charts (<code>kube-prometheus-stack</code> + <code>loki-stack</code>) · one shared label model gluing it all together.</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 2 —</span><span><a href=\"#summary\">Start ▶</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Executive Summary</div><h1 id=\"the-map-the-whole-route\">🗺️ The Map — The Whole Route</h1></div><span class=\"hmeta\">start here</span></div></div>\r\n<p>Before diving into any tool, here's the whole story — every sentence is a link to its chapter.</p>\r\n<p>We begin in <a href=\"#ch-01\">Part 1 — What is Observability?</a>: the ability to understand what's happening inside a system from the data it produces — <b>without shipping new code to ask a new question</b> — through four pillars: <b>Logs</b>, <b>Metrics</b>, <b>Traces</b>, and <b>Visualization</b>. Then <a href=\"#ch-02\">Part 2</a> puts the three signal types side by side — the single most exam-worthy table in this book — and <a href=\"#ch-02b\">Part 2·b</a> introduces the deployed stack component by component.</p>\r\n<p>Logs first: <a href=\"#ch-03\">Part 3 — Why Loki?</a> (10–20× cheaper — it indexes labels, not text), <a href=\"#ch-03b\">Part 3·b</a> the write/read path pipeline (Distributor → Ingester → Store ← Querier), and <a href=\"#ch-03c\">Part 3·c</a> Promtail's DaemonSet workflow: Discover → Tail → Label → Ship.</p>\r\n<p>Metrics: <a href=\"#ch-04\">Part 4 — Prometheus</a> (pull model, time series, PromQL, service discovery) and <a href=\"#ch-04b\">Part 4·b</a> the four metric sources: node-exporter, kube-state-metrics, cAdvisor, ServiceMonitor/PodMonitor CRDs. Then <a href=\"#ch-05\">Part 5 — Traces</a> (the natural next step) and <a href=\"#ch-06\">Part 6 — Grafana</a>, the memoryless unified UI.</p>\r\n<p>Everything practical: <a href=\"#ch-07\">Part 7</a> the complete data flow · <a href=\"#ch-08\">Part 8</a> the Helm deployment · <a href=\"#ch-08b\">Part 8·b</a> the datasource conflict gotcha + port-forward · <a href=\"#ch-09\">Part 9</a> LogQL &amp; <a href=\"#ch-09b\">PromQL</a> · <a href=\"#ch-10\">Part 10</a> app integration · <a href=\"#ch-11\">Part 11</a> the troubleshooting playbook · <a href=\"#ch-11b\">cleanup</a> · <a href=\"#ch-13\">Part 13</a> the architecture mental model · <a href=\"#ch-13b\">the terms glossary</a> · <a href=\"#ch-14\">Part 14</a> interview prep, <a href=\"#ch-14b\">cheat sheet</a> &amp; <a href=\"#ch-14c\">quiz</a>. The route is clear. ▶</p>\r\n<div class=\"taskhead\">TASK [The classic debugging flow]<span class=\"hst\">how the signals cooperate</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">📈 Metric alert fires<small> \"error rate jumped\"</small></span>\r\n<span class=\"harrow\">──►</span>\r\n<span class=\"chipr\">🔗 Trace shows which hop got slow</span>\r\n<span class=\"harrow\">──►</span>\r\n<span class=\"chipr\">📜 Log line tells the exact exception</span>\r\n</div>\r\n<p><b>Grafana</b> is the pane of glass where all of this comes together — because Loki uses <b>the exact same label model as Prometheus and Kubernetes</b>, you can pivot from a metric on a pod straight to that pod's logs.</p>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span><b>The unifying idea:</b> each component does exactly one job — Promtail <b>pushes</b> logs, Prometheus <b>pulls</b> metrics, Grafana <b>queries both and displays them</b>. Two transport models, one shared label model (namespace/pod/container/node). No shared databases, no unnecessary complexity.</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a> · <a href=\"../threads/#controller-agent\">Controllers &amp; Agents</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 3 —</span><span><a href=\"#toc\">▤ TOC</a> ▶ <a href=\"#ch-01\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 01</div><h1 id=\"what-is-observability-the-four-pillars\">👁️ What is Observability? <span class=\"en\">— The Four Pillars</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n<p><b>Observability</b> is the ability to understand what is happening inside a system by examining the data it produces — <b>without having to ship new code to ask a new question</b>. It relies on four core pillars:</p>\r\n<div class=\"taskhead\">TASK [The Four Pillars]<span class=\"hst\">and the question each answers</span></div>\r\n<div class=\"grid2\">\r\n<div class=\"pillar\">\r\n<div class=\"ico\">📜</div>\r\n<b>Logs</b>\r\n<div class=\"q\">\"What happened, and what did it say?\"</div>\r\n<p>Discrete, timestamped records of events — the error, the warning, the startup message.</p>\r\n</div>\r\n<div class=\"pillar\">\r\n<div class=\"ico\">📈</div>\r\n<b>Metrics</b>\r\n<div class=\"q\">\"How much, how fast, how often?\"</div>\r\n<p>Numeric measurements over time — CPU, requests per second, response latency.</p>\r\n</div>\r\n<div class=\"pillar\">\r\n<div class=\"ico\">🔗</div>\r\n<b>Traces</b>\r\n<div class=\"q\">\"Where did the time go?\"</div>\r\n<p>The full path a single request takes as it moves across the different services.</p>\r\n</div>\r\n<div class=\"pillar\">\r\n<div class=\"ico\">📊</div>\r\n<b>Visualization</b>\r\n<div class=\"q\">\"Can a human act on this?\"</div>\r\n<p>Turns raw signals into dashboards a human can read and act upon.</p>\r\n</div>\r\n</div>\r\n<p>The first three pillars produce and store the signals — the fourth makes them understandable and actionable.</p>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>The pillars don't overlap — each answers a <b>different kind of question</b>: a <b>Log</b> tells you <i>what happened in detail</i>, a <b>Metric</b> tells you <i>how much and how fast</i>, a <b>Trace</b> tells you <i>where the time went</i>. A full investigation uses all three together.</div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE · Why the definition matters</span>Notice the key phrase: \"without shipping new code to ask a new question.\" You instrument the system <b>once</b>; after that, any new question (\"why was latency high at 2 AM?\", \"which pod threw the error?\") is answered by querying data that <b>already exists</b> — not by redeploying with extra print statements. A good observability system answers questions you didn't anticipate when you built it — unlike traditional monitoring, which only answers pre-written questions.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>The classic interview opener: \"What is Observability, and what are its pillars?\" → <b>Understanding system state from its data without deploying new code</b> · Pillars: <b>Logs · Metrics · Traces · Visualization</b> — with the question each one answers.</div>\r\n<p>⏭️ How do the pillars become actual components? → <a href=\"#ch-02\">Part 2: Logs vs Metrics vs Traces</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 4 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#summary\">Prev</a> · <a href=\"#ch-02\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 02</div><h1 id=\"logs-vs-metrics-vs-traces\">⚖️ Logs vs Metrics vs Traces</h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<p>The three signal types are <b>complementary, not redundant</b>. This table is the single most exam-worthy artifact in this guide:</p>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th></th><th>📜 Logs</th><th>📈 Metrics</th><th>🔗 Traces</th></tr>\r\n<tr><td>Question</td><td>What happened, and what did it say?</td><td>How much, how fast, how often?</td><td>Where did the time go?</td></tr>\r\n<tr><td>Nature</td><td>Discrete, timestamped event records</td><td>Numeric measurements over time</td><td>Full journey of one request across services</td></tr>\r\n<tr><td>Shape</td><td>Free-form text lines</td><td>Time series (name + labels + values)</td><td>Request path through service hops</td></tr>\r\n<tr><td>Stored by</td><td><b>Loki</b></td><td><b>Prometheus</b></td><td><i>Not deployed in this lab</i> (Tempo / Jaeger / Zipkin would be)</td></tr>\r\n<tr><td>Query language</td><td><b>LogQL</b></td><td><b>PromQL</b></td><td>(trace UI)</td></tr>\r\n<tr><td>Best for</td><td>Reading the <i>exact</i> content of an event (\"show me the stack trace\")</td><td>Trends, rates, aggregation, alerting, dashboards</td><td>Latency breakdown across a multi-service request</td></tr>\r\n</table></div></div><div class=\"mark m-tip\"><span class=\"tag\">WHEN TO USE LOKI / PROMETHEUS / GRAFANA</span>use when Loki stores log lines for exact errors · use when Prometheus scrapes numeric signals for alerts · use when Grafana unifies both into dashboards · avoid when logs serve as metrics · avoid when metrics replace trace journeys. <a href=\"../read/platforms-roadmaps.html#s29n\">Tool vs Tool — The Whole Field</a></div>\r\n<div class=\"taskhead\">TASK [How they work together]<span class=\"hst\">the classic debugging flow</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">🚨 A <b>metric</b> alert fires<small> \"error rate jumped\"</small></span>\r\n<span class=\"harrow\">──►</span>\r\n<span class=\"chipr\">🔗 a <b>trace</b> shows which hop got slow</span>\r\n<span class=\"harrow\">──►</span>\r\n<span class=\"chipr\">📜 a <b>log</b> line tells you the exact exception</span>\r\n</div>\r\n<p><b>Grafana</b> is the pane of glass where all of this comes together.</p>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Because Loki uses <b>the exact same label model as Prometheus and Kubernetes</b>, you can pivot from a metric on a pod straight to that pod's logs. See a CPU spike on <code>pod X, namespace Y</code> in a Prometheus panel → query <code>{namespace=\"Y\", pod=\"X\"}</code> in Loki → read the logs from exactly that window. <b>Zero extra configuration produces this.</b></div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Logs = <b>what happened</b> (Loki/LogQL) · Metrics = <b>how much/how fast</b> (Prometheus/PromQL) · Traces = <b>where the time went</b> (not in this lab) · Debug flow: <b>alert → trace → log</b>, all visible in Grafana.</div>\r\n<p>⏭️ Now meet the components that store these signals → <a href=\"#ch-02b\">Part 2·b: The Core Stack</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 5 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-01\">Prev</a> · <a href=\"#ch-02b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 02·b</div><h1 id=\"the-core-stack-at-a-glance\">🧱 The Core Stack <span class=\"en\">— At a Glance</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n<div class=\"taskhead\">TASK [Seven components, seven jobs]<span class=\"hst\">who does what</span></div>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th>Component</th><th>Role</th><th>Installed by</th><th>Runs as</th></tr>\r\n<tr><td><b>📜 Loki</b></td><td>Stores and indexes logs</td><td><code>loki-stack</code></td><td>Log backend</td></tr>\r\n<tr><td><b>📜 Promtail</b></td><td>Tails container logs on every node and ships them to Loki</td><td><code>loki-stack</code></td><td><b>DaemonSet</b></td></tr>\r\n<tr><td><b>📈 Prometheus</b></td><td>Scrapes and stores metrics as time series</td><td><code>kube-prometheus-stack</code></td><td>Metrics backend</td></tr>\r\n<tr><td><b>🖥️ node-exporter</b></td><td>Exposes host-level metrics</td><td><code>kube-prometheus-stack</code></td><td><b>DaemonSet</b></td></tr>\r\n<tr><td><b>📦 kube-state-metrics</b></td><td>Exposes Kubernetes object state metrics</td><td><code>kube-prometheus-stack</code></td><td>Deployment</td></tr>\r\n<tr><td><b>🚨 Alertmanager</b></td><td>Routes PromQL alert conditions to Slack/email/PagerDuty</td><td><code>kube-prometheus-stack</code></td><td><span class=\"stbad st-chg\">DISABLED IN THIS LAB</span></td></tr>\r\n<tr><td><b>📊 Grafana</b></td><td>Queries both backends, renders dashboards</td><td><code>kube-prometheus-stack</code></td><td>Deployment</td></tr>\r\n</table></div></div>\r\n<div class=\"taskhead\">TASK [Two transports, one label model]<span class=\"hst\">the asymmetry</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">📜 Promtail</span>\r\n<span class=\"harrow\">── PUSH (HTTP batches) ──►</span>\r\n<span class=\"chipr\">🗄️ Loki</span>\r\n</div>\r\n<div class=\"frow\">\r\n<span class=\"chipr\">📈 Prometheus</span>\r\n<span class=\"harrow\">◄── PULL (scrape interval) ──</span>\r\n<span class=\"chipr\">🎯 targets /metrics</span>\r\n</div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span><b>Key asymmetry to remember:</b> Promtail <b>pushes</b> logs to Loki; Prometheus <b>pulls</b> metrics from targets. Two different transport models — <b>one shared label model</b> (namespace / pod / container / node) that makes the stack feel like a single system.</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · Modularity</span>These are <b>three fully independent groups</b> — you could <b>swap any one for an alternative</b> (ELK instead of Loki, for example) because they don't talk to each other directly. They only meet at Grafana. <b>That separation is why the stack stays flexible.</b></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>Grafana <b>stores nothing</b> — it's display only. Any dashboard without live Data Sources = an empty page. The data always lives in Loki or Prometheus. And note that Grafana itself is installed <b>by <code>kube-prometheus-stack</code></b>, not standalone — this exact fact causes the datasource conflict in <a href=\"#ch-08b\">Part 8·b</a>.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Stack: <b>Loki + Promtail (Logs) · Prometheus + exporters (Metrics) · Grafana (Visualization)</b> · Push = logs, Pull = metrics · Promtail &amp; node-exporter run as <b>DaemonSets</b> · Alertmanager disabled in the lab · Components are swappable — they meet only at Grafana.</div>\r\n<p>⏭️ Starting with the first pillar: why Loki specifically? → <a href=\"#ch-03\">Part 3</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 6 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-02\">Prev</a> · <a href=\"#ch-03\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 03 · Logs 1/3</div><h1 id=\"why-loki-the-philosophy-amp-the-differences\">📜 Why Loki? <span class=\"en\">— The Philosophy &amp; the Differences</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<p><b>Loki</b> is a horizontally-scalable, multi-tenant log aggregation system built by <b>Grafana Labs</b>. It stands apart from full-text systems like ELK for four essential reasons:</p>\r\n<div class=\"grid2\">\r\n<div class=\"panel\">\r\n<p>💰 Cost-Effective — the cheapest</p>\r\n<p><b>10–20× cheaper for storage</b>, because Loki indexes <b>only metadata (labels)</b> — not the full text of every log line. Light indexing = light storage bill.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>🗄️ Storage — cheap tiers</p>\r\n<p>Logs are compressed into <b>chunks</b> and stored in <b>cheap object storage</b> (or a local filesystem in labs) — no massive search nodes needed.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>🔍 Querying — LogQL</p>\r\n<p>You query Loki with <b>LogQL</b> — a language <b>deliberately designed</b> to be similar to PromQL. Learn one and the other feels familiar.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>🔗 Integration — native fit</p>\r\n<p>Native <b>Grafana integration</b> (no separate UI needed), and it uses the <b>exact same label model as Kubernetes and Prometheus</b>.</p>\r\n</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [Loki vs ELK — the difference in one line]<span class=\"hst\">the trade-off</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">ELK: indexes full text → powerful text search 💪</span>\r\n<span class=\"harrow\">⇄</span>\r\n<span class=\"chipr\">Loki: indexes labels only → 10–20× cheaper 💰</span>\r\n</div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · The mental model + the philosophy</span>Think of Loki as <b>\"Prometheus for logs.\"</b> And the philosophy in one line: <b>\"don't index what you won't query.\"</b> Indexing metadata (which namespace? which pod? which container?) is enough to filter millions of lines, leaving the raw text to be read only at query time — that's the root cause of both its cheapness and its query behavior: <b>label selectors are fast, line filters are done on the fly</b>.</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>The trade-off is real: because Loki doesn't index the log text itself, free-form full-text search is weaker than ELK. You query <b>by labels first</b>, then narrow with LogQL. In Kubernetes environments with good labels — exactly our case — the trade-off pays off enormously.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>The four reasons: <b>Cost (10–20× cheaper — labels-only indexing) · Storage (chunks in cheap object storage) · LogQL (similar to PromQL) · native Grafana integration + same label model</b>. Mental model: <b>\"Prometheus for logs\"</b> · Philosophy: <b>\"don't index what you won't query.\"</b></div>\r\n<p>⏭️ How does Loki work internally? The write and read paths: → <a href=\"#ch-03b\">Part 3·b</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 7 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-02b\">Prev</a> · <a href=\"#ch-03b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 03·b · Logs 2/3</div><h1 id=\"loki-architecture-write-path-amp-read-path\">🏗️ Loki Architecture <span class=\"en\">— Write Path &amp; Read Path</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<h3 id=\"3-athe-five-stage-pipeline\"><span class=\"n\">3-A</span>The five-stage pipeline</h3>\r\n<p>Logs travel through Loki's architecture along a specific path — writes flow down the pipeline, reads come back from the Store:</p>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<div class=\"blk\">1️⃣ Promtail<small>ships from the nodes</small></div>\r\n<span class=\"harrow\">──►</span>\r\n<div class=\"blk\">2️⃣ Distributor<small>validates &amp; hashes streams</small></div>\r\n<span class=\"harrow\">──►</span>\r\n<div class=\"blk\">3️⃣ Ingester<small>batches into chunks, writes</small></div>\r\n</div>\r\n<div class=\"darr\">▼</div>\r\n<div class=\"frow\">\r\n<div class=\"blk\">4️⃣ Store<small>chunks + index (object storage / disk)</small></div>\r\n<span class=\"harrow\">◄──</span>\r\n<div class=\"blk\">5️⃣ Querier<small>executes LogQL from Grafana</small></div>\r\n</div>\r\n<p>WRITE: container log files → Promtail → Distributor → Ingester → Store  ·  READ: Grafana —LogQL→ Querier → reads chunks + index from Store/Ingester</p>\r\n</div>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th>Component</th><th>Job</th></tr>\r\n<tr><td>1. Promtail</td><td>Ships logs from the nodes</td></tr>\r\n<tr><td>2. Distributor</td><td><b>Validates</b> and <b>hashes</b> the incoming log streams</td></tr>\r\n<tr><td>3. Ingester</td><td>Batches the streams into <b>chunks</b> and writes them</td></tr>\r\n<tr><td>4. Store</td><td>Stores the chunks <b>and the index</b> (object storage or local disk)</td></tr>\r\n<tr><td>5. Querier</td><td>Executes the LogQL queries coming from Grafana</td></tr>\r\n</table></div></div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>A <b>log stream</b> = a <b>unique combination of labels</b>. Every distinct label set is its own stream — which is exactly why the labels Promtail attaches matter so much (<a href=\"#ch-03c\">Part 3·c</a>).</div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE · Reads vs writes</span>Writes flow left→right down the pipeline (1→4). Reads never touch the write path's front: the <b>Querier</b> (5) pulls already-stored chunks + index from the Store (and Ingester for recent, not-yet-flushed data).</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>The pipeline: <b>Promtail → Distributor (validates &amp; hashes) → Ingester (chunks) → Store (chunks + index) ← Querier (LogQL)</b>. A log stream = <b>a unique label combination</b>.</div>\r\n<p>⏭️ The component that feeds stage 1 — why it's a DaemonSet: → <a href=\"#ch-03c\">Part 3·c: Promtail</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a> · <a href=\"../threads/#controller-agent\">Controllers &amp; Agents</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 8 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-03\">Prev</a> · <a href=\"#ch-03c\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 03·c · Logs 3/3</div><h1 id=\"promtail-workflow-why-a-daemonset-the-4-steps\">🚚 Promtail Workflow <span class=\"en\">— Why a DaemonSet + the 4 Steps</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<p>Promtail runs as a <b>DaemonSet</b> — <b>one pod per Kubernetes node</b>. Why? Because container logs are <b>files on each node's local filesystem</b>. A Promtail pod on node A physically cannot read node B's <code>/var/log/pods</code>. <b>Node-local data ⇒ node-local collector.</b></p>\r\n<div class=\"taskhead\">TASK [The four steps]<span class=\"hst\">discover → tail → label → ship</span></div>\r\n<div class=\"grid4\">\r\n<div class=\"panel\"><p>1️⃣ Discover</p><p>Uses Kubernetes <b>service discovery</b> to find every pod running <b>on its node</b>.</p></div>\r\n<div class=\"panel\"><p>2️⃣ Tail</p><p>Reads container log files directly from <code>/var/log/pods</code> — like a <code>tail -f</code>.</p></div>\r\n<div class=\"panel\"><p>3️⃣ Label</p><p>Attaches K8s metadata as labels: <b>namespace, pod, container, node</b>.</p></div>\r\n<div class=\"panel\"><p>4️⃣ Ship</p><p>Batches log lines and <b>pushes to Loki's distributor over HTTP</b>.</p></div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · Labels are the gear in the machine</span>Step 3 matters more than it looks: because Promtail's labels are <b>identical to Prometheus's labels</b>, switching between logs and metrics in Grafana is seamless — <b>same namespace, same pod, same language</b> — and logs and metrics are <b>cross-correlatable by default</b>. See a CPU spike on <code>pod X, namespace Y</code> in a Prometheus panel → query <code>{namespace=\"Y\", pod=\"X\"}</code> in Loki → read the logs from exactly that window. <b>Zero extra configuration produces this.</b></div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT · Label cardinality</span>Labels are indexed, so they're relatively expensive in Loki — never attach unbounded varying values (like <code>user_id</code>) as labels. Keep it to stable, structured ones: <b>namespace, app, pod, container, node</b>.</div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE</span>Step 4 completes the push model: Promtail <b>pushes</b> batches over HTTP — the opposite of Prometheus, which <b>pulls</b> from targets. Same labels, opposite transport direction.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Promtail = <b>DaemonSet</b> (one pod per node — logs are node-local files in <code>/var/log/pods</code>) · Steps: <b>Discover → Tail → Label (same K8s labels as Prometheus) → Ship (HTTP push)</b> · Shared labels = free log↔metric correlation.</div>\r\n<p>⏭️ From logs to metrics: → <a href=\"#ch-04\">Part 4: Prometheus</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 9 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-03b\">Prev</a> · <a href=\"#ch-04\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 04 · Metrics 1/2</div><h1 id=\"prometheus-fundamentals\">📈 Prometheus <span class=\"en\">— Fundamentals</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<p><b>Prometheus</b> is an open-source monitoring system that uses a <b>pull model</b>: it <b>scrapes</b> metrics from targets on a regular interval, rather than waiting for applications to push data.</p>\r\n<div class=\"taskhead\">TASK [The three core concepts]<span class=\"hst\">storage · querying · alerting</span></div>\r\n<div class=\"grid3\">\r\n<div class=\"panel\">\r\n<p>🗄️ Storage</p>\r\n<p>Every measurement is a <b>Time Series</b>: a <b>metric name</b> + <b>key/value labels</b> + a <b>sequence of timestamped values</b>. Example: <code>container_cpu_usage_seconds_total{namespace=\"app\", pod=\"api-7d9f\"}</code> — labels are the dimensions you aggregate by.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>🔍 Querying — PromQL</p>\r\n<p>A powerful query language for <b>aggregating</b>, <b>filtering</b>, and computing <b>rates</b> over time series.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>🚨 Alerting — Alertmanager</p>\r\n<p>Pairs with <b>Alertmanager</b> to turn PromQL conditions into <b>routed alerts</b> — Slack, Email, PagerDuty. <i>(Disabled in this lab — but the concept stands.)</i></p>\r\n</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [Why pulling matters]<span class=\"hst\">practical consequences</span></div>\r\n<div class=\"grid2\">\r\n<div class=\"mark m-tip\"><span class=\"tag\">CENTRAL CONTROL</span>The Pull Model gives Prometheus full control: it knows <b>when</b> the last scrape happened and decides the cadence and the target list — apps don't need to know where Prometheus lives. Just expose a <code>/metrics</code> endpoint, nothing more.</div>\r\n<div class=\"mark m-ok\"><span class=\"tag\">FAILURE IS VISIBLE</span>A dead target doesn't just leave a gap in the data — its <code>up</code> metric goes to <code>0</code>. A target that won't respond to a scrape = down. You can literally <b>query whether monitoring works</b>.</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [Service discovery]<span class=\"hst\">no manual IP lists</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">In Kubernetes, Prometheus <b>automatically finds targets</b></span>\r\n<span class=\"harrow\">via</span>\r\n<span class=\"chipr\">service discovery + Custom Resources (CRDs)</span>\r\n</div>\r\n<p>Nobody maintains a list of pod IPs — pods are ephemeral anyway; the list would be stale in minutes.</p>\r\n</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>Every unique combination of labels creates a <b>new series</b> — the same label-explosion issue as Loki: too many varying labels = an explosion in series count.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Prometheus: <b>Pull Model</b> · Time series = <b>name + labels + timestamped values</b> · Querying: <b>PromQL</b> · Alerting: <b>Alertmanager</b> (disabled here) · Target discovery: <b>automatic via service discovery + CRDs</b> · Dead target = <code>up == 0</code>.</div>\r\n<p>⏭️ Where do the metrics actually come from? → <a href=\"#ch-04b\">Part 4·b: The Metric Sources</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 10 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-03c\">Prev</a> · <a href=\"#ch-04b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 04·b · Metrics 2/2</div><h1 id=\"metric-sources-know-who-exposes-what\">🛰️ Metric Sources <span class=\"en\">— Know Who Exposes What</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th>Component</th><th>Where it runs</th><th>What it exposes</th><th>The question it answers</th></tr>\r\n<tr><td>🖥️ node-exporter</td><td><b>DaemonSet</b> (one pod per node)</td><td><b>Host-level</b> metrics: CPU, memory, disk, network</td><td>\"Is the <b>machine</b> itself healthy?\"</td></tr>\r\n<tr><td>📦 kube-state-metrics</td><td>Watches the <b>Kubernetes API</b></td><td><b>Object state</b>: pod status, deployment replicas, restarts</td><td>\"Does Kubernetes <i>think</i> everything is fine?\"</td></tr>\r\n<tr><td>⚙️ cAdvisor</td><td><b>Built into the kubelet</b></td><td><b>Per-container</b> resource usage (actual CPU/memory each container consumes)</td><td>\"Which <b>container</b> is eating resources?\"</td></tr>\r\n<tr><td>🎯 ServiceMonitor / PodMonitor</td><td>CRDs — not pods at all</td><td>Declarative rules for <b>which Services/Pods Prometheus should scrape</b></td><td>\"How does Prometheus find <i>my app</i>?\"</td></tr>\r\n</table></div></div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · Drill this distinction</span>node-exporter = <b>machine</b> · kube-state-metrics = <b>Kubernetes objects</b> · cAdvisor = <b>containers</b>. Three layers of \"is it healthy\" — three different components. And the ServiceMonitor CRD is what wires your app into Prometheus with zero manual config.</div>\r\n<div class=\"taskhead\">TASK [Who watches what?]<span class=\"hst\">the layering</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">🖥️ node-exporter<small> → the node itself</small></span>\r\n<span class=\"chipr\">⚙️ cAdvisor<small> → the containers</small></span>\r\n</div>\r\n<div class=\"frow\">\r\n<span class=\"chipr\">📦 kube-state-metrics<small> → K8s object state</small></span>\r\n<span class=\"chipr\">🎯 ServiceMonitor<small> → which targets get scraped</small></span>\r\n</div>\r\n</div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE · Why CRDs matter</span>Instead of asking \"which IPs do I scrape?\" — you create a ServiceMonitor naming the Service by label, and the Helm chart that deploys the app ships its ServiceMonitor along. The result: <b>deploying an app = monitoring it automatically</b>. Deploying the CRD <i>is</i> the configuration. (Full example in <a href=\"#ch-10\">Part 10</a>.)</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span><b>node-exporter</b> (DaemonSet — host metrics) · <b>kube-state-metrics</b> (API server — object state) · <b>cAdvisor</b> (in the kubelet — per-container) · <b>ServiceMonitor/PodMonitor CRDs</b> (declarative scrape targeting, auto-wired by Helm).</div>\r\n<p>⏭️ The third pillar: the journey of a single request → <a href=\"#ch-05\">Part 5: Traces</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 11 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-04\">Prev</a> · <a href=\"#ch-05\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 05</div><h1 id=\"traces-the-journey-of-a-request\">🔗 Traces <span class=\"en\">— The Journey of a Request</span></h1></div><span class=\"hmeta\">🟢 4 MIN</span></div></div>\r\n<p>A <b>trace</b> records the full journey of a <b>single request</b> as it moves through multiple services:</p>\r\n<div class=\"taskhead\">TASK [The journey of one request]<span class=\"hst\">a worked example</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">🌐 API Gateway<small> 2ms</small></span>\r\n<span class=\"harrow\">──►</span>\r\n<span class=\"chipr\">🔐 Auth Service<small> 15ms</small></span>\r\n<span class=\"harrow\">──►</span>\r\n<span class=\"chipr\">📦 Order Service<small> 40ms</small></span>\r\n<span class=\"harrow\">──►</span>\r\n<span class=\"chipr\">🗄️ DB Query<small> 120ms ⚠</small></span>\r\n</div>\r\n<p>The trace reveals instantly: <b>most of the time went to the DB Query</b> — no guessing, no manually checking every service.</p>\r\n</div>\r\n<h3 id=\"5-1the-purpose\"><span class=\"n\">5.1</span>The purpose</h3>\r\n<p>Traces show <b>exactly where time was spent</b> during a request. Metrics tell you <i>that</i> requests are slow; traces tell you <i>which hop</i> made them slow — which service was slow, which call repeated, where the real bottleneck lives.</p>\r\n<h3 id=\"5-2the-tools\"><span class=\"n\">5.2</span>The tools</h3>\r\n<p>Tracing typically uses <b>Grafana Tempo</b>, <b>Jaeger</b>, or <b>Zipkin</b>, with applications instrumented via <b>OpenTelemetry</b>.</p>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE · In this lab</span><b>Traces are not deployed in this specific lab</b> — but they represent <b>the natural next step</b> once logs (Loki) and metrics (Prometheus) are in place. Two of the three signals are already running.</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>When someone tells you \"the API is slow\" — Logs tell you <i>what happened</i>, Metrics tell you <i>how slow</i>, but only the <b>Trace</b> tells you <b>exactly where</b> inside the request journey the time went.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>A Trace = <b>the journey of one request across multiple services</b> · Purpose: <b>where the time was spent</b> · Tools: <b>Grafana Tempo / Jaeger / Zipkin</b> via <b>OpenTelemetry</b> · <b>not deployed in this lab</b> — the next step.</div>\r\n<p>⏭️ The fourth pillar: the window into everything → <a href=\"#ch-06\">Part 6: Grafana</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 12 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-04b\">Prev</a> · <a href=\"#ch-06\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 06</div><h1 id=\"grafana-the-unified-ui\">📊 Grafana <span class=\"en\">— The Unified UI</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n<p><b>Grafana</b> is the unified UI for observability — the pane of glass where logs and metrics meet.</p>\r\n<div class=\"taskhead\">TASK [Four concepts]<span class=\"hst\">data · config · dashboards · explore</span></div>\r\n<div class=\"grid2\">\r\n<div class=\"panel\">\r\n<p>🔌 Data Handling</p>\r\n<p>Grafana <b>does not store data itself</b> — it connects to <b>Data Sources</b> (Prometheus, Loki) and <b>queries them live</b> on every panel refresh. Wipe the backends and Grafana has nothing to show — <b>it's a lens, not a database</b>.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>⚙️ Configuration</p>\r\n<p>Each Data Source requires: a <b>URL</b> + <b>authentication</b> + the <b>query language</b> it should speak (<b>PromQL</b> or <b>LogQL</b>).</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>📊 Dashboards &amp; Panels</p>\r\n<p>A <b>Dashboard is a collection of Panels</b>. Each panel runs a query and renders it as a <b>graph, table, log stream, or gauge</b>. Dashboards are <b>JSON</b> — version-controlled, or imported from <code>grafana.com/dashboards</code> by numeric ID.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>🔍 Explore Mode</p>\r\n<p>Run <b>ad-hoc PromQL or LogQL</b> queries without building a dashboard — the go-to tool for debugging (\"just show me the errors from that namespace <i>right now</i>\").</p>\r\n</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [The hierarchy inside Grafana]<span class=\"hst\">the hierarchy</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">📊 Dashboard</span>\r\n<span class=\"harrow\">◂ contains</span>\r\n<span class=\"chipr\">🧩 Panels</span>\r\n<span class=\"harrow\">◄ query from</span>\r\n<span class=\"chipr\">🔌 Data Source</span>\r\n<span class=\"harrow\">◄ which is</span>\r\n<span class=\"chipr\">🗄️ Loki / 📈 Prometheus</span>\r\n</div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Grafana is deliberately memoryless: <b>every panel = a live query</b> at the moment of viewing. Nobody asks \"is the dashboard up to date?\" — it's up to date by definition, because it queries the source directly on every load.</div>\r\n<div class=\"mark m-ok\"><span class=\"tag\">✅ EXPLOIT THIS · Dashboards as code</span>Dashboards are JSON — <b>commit them to Git</b>. A lost dashboard = <b>restore from Git</b>; an intentional change = a <b>Pull Request</b> reviewed like any other code. Version-controlling dashboards is a feature to exploit, not an accident.</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT · Deployment detail</span>In this stack, Grafana is <b>installed by <code>kube-prometheus-stack</code></b>, not deployed standalone. That fact is <b>exactly what causes the datasource conflict</b> in <a href=\"#ch-08b\">Part 8·b</a> — the single best \"bug I debugged\" story in this guide.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Grafana: <b>stores nothing — live Data Sources</b> · Data Source = <b>URL + Auth + Query Language</b> · Dashboard = set of Panels (graph/table/logs/gauge) · Dashboards = <b>JSON → Git: restore + PR review</b> · Explore = <b>ad-hoc debugging</b>.</div>\r\n<p>⏭️ All the pieces are ready — how do they fit together in Kubernetes? → <a href=\"#ch-07\">Part 7</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 13 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-05\">Prev</a> · <a href=\"#ch-07\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 07</div><h1 id=\"how-it-all-fits-together-in-kubernetes\">🧩 How It All Fits Together <span class=\"en\">— in Kubernetes</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<div class=\"taskhead\">TASK [The complete data flow]<span class=\"hst\">six steps, end to end</span></div>\r\n<div class=\"zone\">\r\n<ol>\r\n<li><b>Application pods</b> write logs and (optionally) expose <code>/metrics</code>.</li>\r\n<li>On every node, <b>Promtail</b> (DaemonSet) tails <code>/var/log/pods</code>, labels each line with Kubernetes metadata, and <b>pushes</b> batches to Loki's distributor.</li>\r\n<li>On every node, <b>node-exporter</b> (DaemonSet) exposes host metrics; <b>cAdvisor</b> (in the kubelet) exposes per-container metrics; <b>kube-state-metrics</b> exposes object state.</li>\r\n<li><b>Prometheus pulls</b> all of those metrics on a scrape interval, discovering targets via Kubernetes service discovery and CRDs (ServiceMonitor/PodMonitor).</li>\r\n<li><b>Grafana</b> holds both as data sources and <b>queries Prometheus (PromQL)</b> and <b>Loki (LogQL)</b> live.</li>\r\n<li>You open Grafana in a browser through a <b>port-forward tunnel</b> and see everything.</li>\r\n</ol>\r\n</div>\r\n<div class=\"taskhead\">TASK [Two transports, one label model]<span class=\"hst\">the glue</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">📜 Promtail</span>\r\n<span class=\"harrow\">── <b>pushes</b> logs (HTTP) ──►</span>\r\n<span class=\"chipr\">🗄️ Loki</span>\r\n</div>\r\n<div class=\"frow\">\r\n<span class=\"chipr\">📈 Prometheus</span>\r\n<span class=\"harrow\">◄── <b>pulls</b> metrics (scrape) ──</span>\r\n<span class=\"chipr\">🖥️ node-exporter · cAdvisor · kube-state-metrics · apps</span>\r\n</div>\r\n<p>But both carry the <b>same labels</b> — namespace / pod / container / node — which is what makes the stack feel like one system.</p>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Logs are <b>pushed</b>; metrics are <b>pulled</b>. The transport directions differ, but the <b>label vocabulary is identical</b> — that shared label model is the glue. It's why one label pivot in Grafana jumps you from a CPU graph to the exact log lines that explain it.</div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE · Access pattern</span>Grafana is a <code>ClusterIP</code> Service — reachable only from <i>inside</i> the cluster. From your laptop you reach it via <code>kubectl port-forward</code> (full command + decode in <a href=\"#ch-08b\">Part 8·b</a>).</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Flow: <b>apps/nodes produce → Promtail pushes logs → Loki · Prometheus pulls metrics → TSDB · Grafana queries both live → browser via port-forward</b>. Push ≠ Pull, but labels are shared.</div>\r\n<p>⏭️ Time to actually deploy this — with two Helm commands: → <a href=\"#ch-08\">Part 8: Deployment</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 14 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-06\">Prev</a> · <a href=\"#ch-08\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 08 · Deployment 1/2</div><h1 id=\"helm-kube-prometheus-stack\">🚀 Helm + kube-prometheus-stack</h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n<p><b>Helm</b> is a <b>package manager for Kubernetes</b>. It bundles all necessary manifests — Deployments, Services, ConfigMaps, CRDs — into <b>\"charts.\"</b> Installing a chart creates a <b>release</b>. Charts live in <b>repositories</b> you add to your host. Instead of dozens of hand-written YAML files, <b>two Helm commands</b> deploy the entire platform — including default dashboards and wired-up data sources. <b>Helm turned a week-long project into two commands.</b></p>\r\n<div class=\"taskhead\">TASK [Setup — repos + namespace]<span class=\"hst\">best practice: dedicated namespace</span></div>\r\n<div class=\"code mini\"><span class=\"g\"># add both chart repositories, refresh indexes, create the namespace</span>\r\nhelm repo add prometheus-community <span class=\"s\">https://prometheus-community.github.io/helm-charts</span>\r\nhelm repo add grafana <span class=\"s\">https://grafana.github.io/helm-charts</span>\r\nhelm repo update\r\nkubectl create namespace <span class=\"p\">observability</span> <span class=\"g\"># keeps monitoring separate from app workloads</span></div>\r\n<div class=\"taskhead\">TASK [Chart 1: kube-prometheus-stack]<span class=\"hst\">one chart, many components</span></div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">INSTALLS</span><b>Prometheus · Alertmanager · Grafana · node-exporter · kube-state-metrics · ServiceMonitor/PodMonitor CRDs · default Kubernetes dashboards</b> — in one shot.</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠ RESOURCE MANAGEMENT</span>By default this chart <b>requests more CPU and RAM than a small Minikube cluster can handle</b> — install it bare and pods sit in <code>Pending</code> because the scheduler can't fit their requests anywhere. You must <b>drastically trim resource requests and limits for every component</b> with <code>--set</code> flags:</div>\r\n<div class=\"code mini\">helm upgrade --install kube-prometheus-stack prometheus-community/kube-prometheus-stack \\\r\n  -n observability \\\r\n  --set alertmanager.enabled=<span class=\"y\">false</span> \\\r\n  --set prometheus.prometheusSpec.retention=<span class=\"s\">6h</span> \\\r\n  --set grafana.adminPassword=<span class=\"s\">admin123</span> \\\r\n  --set prometheus.prometheusSpec.resources.requests.cpu=<span class=\"s\">100m</span> \\\r\n  --set prometheus.prometheusSpec.resources.requests.memory=<span class=\"s\">256Mi</span> \\\r\n  --set grafana.resources.requests.cpu=<span class=\"s\">50m</span> \\\r\n  --set grafana.resources.requests.memory=<span class=\"s\">128Mi</span>\r\n<span class=\"g\"># ...similar trimming for kube-state-metrics &amp; node-exporter.</span>\r\n<span class=\"g\"># Exact value keys: helm show values prometheus-community/kube-prometheus-stack</span></div>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th>Override</th><th>Why</th></tr>\r\n<tr><td>Resources trimmed (every component)</td><td>Chart defaults assume beefy nodes; Minikube pods go <code>Pending</code> otherwise</td></tr>\r\n<tr><td><code>retention=6h</code></td><td>TSDB storage grows with retention; a lab needs no history — 6h is plenty for debugging</td></tr>\r\n<tr><td><code>alertmanager.enabled=false</code></td><td>No alert routing needed in a lab → fewer pods, less RAM</td></tr>\r\n<tr><td><code>adminPassword=admin123</code></td><td>The lab's Grafana credentials (<code>admin</code> / <code>admin123</code>)</td></tr>\r\n</table></div></div>\r\n<div class=\"mark m-key\"><span class=\"tag\">🔑 IDEMPOTENCY RULE</span><b>Always use <code>helm upgrade --install</code>, never plain <code>helm install</code>.</b> <code>helm upgrade --install</code> is <b>safe to re-run</b>: if the release exists it upgrades in-place; if not, it installs. Plain <code>helm install</code> <b>fails</b> on a second run.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Helm = <b>K8s package manager</b> (charts → releases, from repos) · <b>two commands = the whole platform</b> · Minikube needs <b>trimmed resource requests</b> or pods go <code>Pending</code> · <b>retention 6h</b> saves disk · <b>helm upgrade --install</b> = idempotent.</div>\r\n<p>⏭️ Chart 2 — and the one non-obvious gotcha: → <a href=\"#ch-08b\">Part 8·b</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 15 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-07\">Prev</a> · <a href=\"#ch-08b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 08·b · Deployment 2/2</div><h1 id=\"loki-stack-the-gotcha-port-forward\">⚠️ loki-stack + The Gotcha <span class=\"en\">+ Port-Forward</span></h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n<div class=\"code mini\">helm upgrade --install loki-stack grafana/loki-stack \\\r\n  -n observability \\\r\n  --set grafana.sidecar.datasources.defaultDatasourceEnabled=<span class=\"y\">false</span> <span class=\"g\"># ← THE critical flag</span></div>\r\n<div class=\"taskhead\">TASK [⚠ The datasource provisioning conflict]<span class=\"hst\">the one non-obvious gotcha</span></div>\r\n<div class=\"zone\">\r\n<ol>\r\n<li><code>loki-stack</code> ships <b>its own Grafana data-source ConfigMap</b> for Loki.</li>\r\n<li>The <b>Grafana sidecar</b> (in the Grafana installed by <code>kube-prometheus-stack</code>) <b>auto-discovers</b> datasource ConfigMaps and loads them — Loki appears with zero manual config. Nice.</li>\r\n<li><b>The conflict:</b> <code>kube-prometheus-stack</code> marks <b>Prometheus</b> as the <b>default</b> datasource. <code>loki-stack</code> <b>also tries to mark Loki as default</b>.</li>\r\n<li>Grafana allows <b>exactly one default datasource</b>. Two defaults = <b>\"Datasource provisioning error\"</b> → Grafana <b>crashes → restarts → crashes → <code>CrashLoopBackOff</code></b>.</li>\r\n</ol>\r\n</div>\r\n<div class=\"grid2\">\r\n<div class=\"mark m-ok\"><span class=\"tag\">✅ THE FIX</span>Install Loki with <code>--set grafana.sidecar.datasources.defaultDatasourceEnabled=false</code> — Loki still becomes a datasource, just <b>not the default</b> (Prometheus stays default).</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">🩹 EMERGENCY REPAIR</span>Already broken? <code>kubectl get configmap -n observability</code> → find the extra datasource ConfigMap → <b>remove <code>isDefault: true</code></b> → restart the Grafana pod.</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [Accessing Grafana — port-forward]<span class=\"hst\">ClusterIP = inside the cluster only</span></div>\r\n<div class=\"code mini\">kubectl port-forward --address 0.0.0.0 -n observability \\\r\n  svc/kube-prometheus-stack-grafana 3000:80\r\n<span class=\"g\"># then open http://localhost:3000 → login admin / admin123</span></div>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th>Piece</th><th>Meaning</th></tr>\r\n<tr><td><code>svc/kube-prometheus-stack-grafana</code></td><td>The Service to tunnel to</td></tr>\r\n<tr><td><code>-n observability</code></td><td>The namespace the Service lives in</td></tr>\r\n<tr><td><code>3000:80</code></td><td><b>local port 3000 → Service port 80</b></td></tr>\r\n<tr><td><code>--address 0.0.0.0</code></td><td>Bind on <b>all host interfaces</b>, not loopback only — <b>required on Windows/WSL</b>, otherwise <i>connection refused</i> from the Windows side</td></tr>\r\n</table></div></div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">DASHBOARDS</span><b>Pre-installed</b> (by kube-prometheus-stack): cluster compute resources, namespaces, nodes, Kubelet — all Prometheus-backed. <b>Not included:</b> Loki dashboards — import via UI (<b>Dashboards → Import → ID → Load</b>): <b>13639</b> (Kubernetes Logs) · <b>12611</b> (Log volume) — or skip dashboards and use <b>Explore</b>.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Two charts both provisioning a <b>default</b> datasource → Grafana crash-loops (it allows exactly one) → fix: <code>defaultDatasourceEnabled=false</code> · Grafana is <b>ClusterIP</b> → <code>port-forward</code> with <code>--address 0.0.0.0</code> on WSL → <code>admin/admin123</code> · Import dashboards <b>13639 / 12611</b>.</div>\r\n<p>⏭️ The stack is up — now query it: → <a href=\"#ch-09\">Part 9: LogQL</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 16 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-08\">Prev</a> · <a href=\"#ch-09\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 09 · Querying 1/2</div><h1 id=\"logql-querying-loki\">🔍 LogQL <span class=\"en\">— Querying Loki</span></h1></div><span class=\"hmeta\">🟡 7 MIN</span></div></div>\r\n<p><b>Framing:</b> two backends, two query languages, one UI. LogQL was <i>deliberately designed to be similar to PromQL</i>, and both select by the <i>same labels</i> — learn one, and the other feels familiar.</p>\r\n<div class=\"taskhead\">TASK [Start in Explore mode]<span class=\"hst\">no dashboard needed</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">Grafana → Explore → pick datasource → run ad-hoc queries</span>\r\n</div>\r\n<div class=\"frow\">\r\n<span class=\"chipr\">🗄️ Loki: {namespace=\"observability\"}<small> → live streams</small></span>\r\n<span class=\"chipr\">📈 Prometheus: up<small> → 1 = healthy, 0 = down</small></span>\r\n</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [LogQL — every query has up to three stages]<span class=\"hst\">selector → pipeline → wrapper</span></div>\r\n<div class=\"grid3\">\r\n<div class=\"panel\"><p>1️⃣ Stream selector</p><p>Labels — <b>indexed, fast</b>. Picks which log streams to read.</p></div>\r\n<div class=\"panel\"><p>2️⃣ Filter pipeline</p><p>Line filters — evaluated at <b>query time</b> on the matched streams.</p></div>\r\n<div class=\"panel\"><p>3️⃣ Metric wrapper</p><p>Turns log counts into <b>numbers</b> — logs become a metric.</p></div>\r\n</div>\r\n<div class=\"code mini\"><span class=\"g\"># 1) Stream selector: all logs from a namespace</span>\r\n<span class=\"p\">{namespace=\"observability\"}</span>\r\n<span class=\"g\"># narrow by pod / container (the labels Promtail attached)</span>\r\n<span class=\"p\">{namespace=\"default\", pod=\"my-app-7d9f8b6c-\", container=\"app\"}</span>\r\n<span class=\"g\"># 2) Line filters: keep / drop lines by content (Loki searches text HERE)</span>\r\n<span class=\"p\">{namespace=\"observability\"}</span> |= <span class=\"s\">\"error\"</span>\r\n<span class=\"p\">{namespace=\"observability\"}</span> |= <span class=\"s\">\"error\"</span> != <span class=\"s\">\"timeout\"</span>\r\n<span class=\"g\"># 3) Metric query: count matching log lines per pod over a 5m window</span>\r\n<span class=\"c\">sum by (pod)</span> (<span class=\"c\">count_over_time</span>(<span class=\"p\">{namespace=\"default\"}</span> |= <span class=\"s\">\"error\"</span> [<span class=\"y\">5m</span>]))</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · Why this ordering matters</span>The label selector runs against the <b>index</b>; the text search runs against the matching streams <b>at query time</b>. That's the direct payoff of Loki's \"index only labels\" design — cheap storage doesn't mean slow queries <i>if your labels are chosen well</i>.</div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">NOTE · The bridge</span>Stage 3 converts <b>logs into a metric</b> (<code>count_over_time</code> over a <code>[5m]</code> range) — structurally a sibling of PromQL's <code>rate()</code>, and the bridge between the two signal types.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>LogQL = <b>stream selector (indexed) → line filters (query-time) → optional metric wrapper</b> · <code>|=</code> keep, <code>!=</code> drop · <code>count_over_time(...[5m])</code> turns error lines into a per-pod rate.</div>\r\n<p>⏭️ The other half of the pair: → <a href=\"#ch-09b\">Part 9·b: PromQL</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 17 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-08b\">Prev</a> · <a href=\"#ch-09b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 09·b · Querying 2/2</div><h1 id=\"promql-querying-prometheus\">📈 PromQL <span class=\"en\">— Querying Prometheus</span></h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<div class=\"taskhead\">TASK [Core examples — annotated by source component]<span class=\"hst\">know who exposes each metric</span></div>\r\n<div class=\"code mini\"><span class=\"g\"># Health of every scrape target (1 = up, 0 = down)</span>\r\n<span class=\"p\">up</span>\r\n<span class=\"g\"># Only the observability stack itself</span>\r\n<span class=\"p\">up{namespace=\"observability\"}</span>\r\n<span class=\"g\"># Per-container CPU rate over 5m — metric from cAdvisor (via kubelet)</span>\r\n<span class=\"c\">sum by (pod)</span> (<span class=\"c\">rate</span>(<span class=\"p\">container_cpu_usage_seconds_total</span>[<span class=\"y\">5m</span>]))\r\n<span class=\"g\"># Container memory right now — cAdvisor</span>\r\n<span class=\"c\">sum by (pod)</span> (<span class=\"p\">container_memory_usage_bytes</span>)\r\n<span class=\"g\"># Node memory available, as a fraction — metric from node-exporter</span>\r\n<span class=\"p\">node_memory_MemAvailable_bytes</span> / <span class=\"p\">node_memory_MemTotal_bytes</span></div>\r\n<div class=\"taskhead\">TASK [Two mechanics worth internalizing]<span class=\"hst\">range vectors &amp; aggregation</span></div>\r\n<div class=\"grid2\">\r\n<div class=\"panel\">\r\n<p>⏱ [5m] = a range vector</p>\r\n<p>Selects <b>many points over 5 minutes</b> — functions like <code>rate()</code> <b>require</b> a range. A single instant value can't produce a rate.</p>\r\n</div>\r\n<div class=\"panel\">\r\n<p>🧮 sum by (pod) = aggregation</p>\r\n<p>Aggregates across labels, <b>keeping <code>pod</code></b> as the grouping dimension — the same labels Loki uses, so results line up across both backends.</p>\r\n</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [Instant vs trend debugging]<span class=\"hst\">pick the right question</span></div>\r\n<div class=\"zone\">\r\n<div class=\"frow\">\r\n<span class=\"chipr\">\"Right now, is it broken?\" → up · raw stream {namespace=\"...\"}</span>\r\n</div>\r\n<div class=\"frow\">\r\n<span class=\"chipr\">\"Trending toward broken?\" → rate() over [5m] · errors/pod · memory fraction graphs</span>\r\n</div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Because both query languages select by the <b>same labels</b>, the same <code>sum by (pod)</code> grouping works on both sides — a per-pod error <i>rate</i> from Loki lines up exactly with a per-pod CPU <i>rate</i> from Prometheus in adjacent Grafana panels.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span><code>up</code> = scrape health · <code>rate(counter[5m])</code> needs a <b>range vector</b> · <code>sum by (pod)</code> keeps the grouping label · cAdvisor → container metrics · node-exporter → <code>node_*</code> metrics.</div>\r\n<p>⏭️ Getting <i>your own app</i> into the picture: → <a href=\"#ch-10\">Part 10: App Integration</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 18 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-09\">Prev</a> · <a href=\"#ch-10\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 10</div><h1 id=\"application-integration\">🔌 Application Integration</h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n<div class=\"taskhead\">TASK [Logs — zero configuration]<span class=\"hst\">it just works</span></div>\r\n<div class=\"mark m-ok\"><span class=\"tag\">✅ LOGS</span><b>Promtail automatically collects logs from every pod in the cluster</b> — no annotations, no CRDs, nothing. Its DaemonSet + Kubernetes service discovery pick up new pods as they appear. Deploy an app, and its logs (already labeled with namespace/pod/container) are in Loki.</div>\r\n<div class=\"taskhead\">TASK [Metrics — two requirements]<span class=\"hst\">opt-in by design</span></div>\r\n<div class=\"zone\">\r\n<ol>\r\n<li>The app must <b>expose a <code>/metrics</code> endpoint on an <code>http</code> port</b> (client libraries exist for every major language, publishing counters/gauges/histograms in Prometheus format).</li>\r\n<li>Create a <b><code>ServiceMonitor</code> Custom Resource</b> whose label selector matches your application — Prometheus discovers it through the CRD (Helm/operator auto-wires the rest).</li>\r\n</ol>\r\n</div>\r\n<div class=\"code mini\"><span class=\"p\">apiVersion</span>: <span class=\"s\">monitoring.coreos.com/v1</span>\r\n<span class=\"p\">kind</span>: <span class=\"s\">ServiceMonitor</span>\r\n<span class=\"p\">metadata</span>:\r\n  <span class=\"p\">name</span>: <span class=\"s\">my-app</span>\r\n<span class=\"p\">namespace</span>: <span class=\"s\">observability</span>\r\n<span class=\"p\">labels</span>:\r\n    <span class=\"p\">release</span>: <span class=\"s\">kube-prometheus-stack</span> <span class=\"g\"># must match what the Prometheus operator selects</span>\r\n<span class=\"p\">spec</span>:\r\n  <span class=\"p\">selector</span>:\r\n    <span class=\"p\">matchLabels</span>:\r\n      <span class=\"p\">app</span>: <span class=\"s\">my-app</span> <span class=\"g\"># selects YOUR app's Service by its labels</span>\r\n<span class=\"p\">namespaceSelector</span>:\r\n    <span class=\"p\">matchNames</span>:\r\n      - <span class=\"s\">default</span> <span class=\"g\"># where the app's Service lives</span>\r\n<span class=\"p\">endpoints</span>:\r\n    - <span class=\"p\">port</span>: <span class=\"s\">http</span> <span class=\"g\"># the NAME of the Service port serving /metrics</span>\r\n<span class=\"p\">path</span>: <span class=\"s\">/metrics</span>\r\n<span class=\"p\">interval</span>: <span class=\"s\">30s</span></div>\r\n<div class=\"grid3\">\r\n<div class=\"panel\"><p>selector.matchLabels</p><p>Finds the app's <b>Service</b>.</p></div>\r\n<div class=\"panel\"><p>endpoints.port</p><p>Refers to the Service port <b>name</b> — hence \"on an <code>http</code> port.\"</p></div>\r\n<div class=\"panel\"><p>release label</p><p>What the operator's discovery matches on — the <b>\"auto-wiring\" Helm provides</b>.</p></div>\r\n</div>\r\n<div class=\"mark m-ok\"><span class=\"tag\">✅ VERIFY IT WORKED</span>Query <code>up{namespace=\"default\"}</code> in Explore — your app should appear with value <code>1</code> within a scrape interval or two.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>Logs = <b>zero config</b> (Promtail auto-collects) · Metrics = <b>/metrics endpoint + ServiceMonitor CRD</b> · <code>release:</code> label connects the CRD to the operator · Verify with <code>up{namespace=\"default\"}</code> == 1.</div>\r\n<p>⏭️ When things go wrong — the playbook: → <a href=\"#ch-11\">Part 11: Troubleshooting</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 19 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-09b\">Prev</a> · <a href=\"#ch-11\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 11 · Playbook 1/2</div><h1 id=\"troubleshooting-playbook-scenarios-1-3\">🛠️ Troubleshooting Playbook <span class=\"en\">— Scenarios 1–3</span></h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n<p>Reason from <b>symptom → diagnosis → root cause → fix</b>. The diagnostic command sequence matters more than memorizing fixes.</p>\r\n<div class=\"zone\">\r\n<p>🔴 Scenario 1 — Pods stuck in Pending</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><td>Symptom</td><td><code>kubectl get pods -n observability</code> → pods sitting in <span class=\"stbad st-fail\">Pending</span>, not starting</td></tr>\r\n<tr><td>Diagnose</td><td><code>kubectl describe pod &lt;pod&gt; -n observability</code> → events show <b><code>FailedScheduling: Insufficient cpu / memory</code></b></td></tr>\r\n<tr><td>Root cause</td><td>Cluster lacks free CPU/memory — the chart's default resource <i>requests</i> don't fit on the Minikube node, and the scheduler will not place a pod whose requests don't fit</td></tr>\r\n<tr><td>Fix</td><td><span class=\"stbad st-ok\">LOWER REQUESTS</span> (the <code>--set</code> overrides from Part 8) or <span class=\"stbad st-ok\">GROW MINIKUBE</span> (<code>--cpus=... --memory=...</code>)</td></tr>\r\n<tr><td>Lesson</td><td><code>Pending</code> = <b>scheduling problem</b> = look at <i>requests vs available</i> before anything else</td></tr>\r\n</table></div>\r\n</div>\r\n<div class=\"zone\">\r\n<p>🔴 Scenario 2 — Grafana OOMKilled</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><td>Symptom</td><td>Grafana restarts repeatedly; <code>kubectl describe pod</code> shows <span class=\"stbad st-fail\">OOMKilled</span> (exit code 137)</td></tr>\r\n<tr><td>Root cause</td><td>The container <b>ran out of memory</b> — it exceeded its own memory <i>limit</i></td></tr>\r\n<tr><td>Diagnose first</td><td><b>Check the node's free memory first</b> (<code>kubectl top nodes</code>) — <b>do not blindly raise the Grafana limit</b></td></tr>\r\n<tr><td>Fix</td><td>Node has headroom → <span class=\"stbad st-ok\">RAISE LIMIT</span> via <code>--set</code>; node exhausted → <span class=\"stbad st-ok\">FREE CAPACITY</span> (disable components, trim pods, grow Minikube)</td></tr>\r\n<tr><td>Lesson</td><td><code>OOMKilled</code> = <b>limit</b> problem; node exhaustion = <b>capacity</b> problem. Diagnose which one you have.</td></tr>\r\n</table></div>\r\n</div>\r\n<div class=\"zone\">\r\n<p>🔴 Scenario 3 — Grafana CrashLoopBackOff with a provisioning error</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><td>Symptom</td><td>Grafana cycles <span class=\"stbad st-fail\">CrashLoopBackOff</span>; logs show <b>\"Datasource provisioning error.\"</b></td></tr>\r\n<tr><td>Diagnose</td><td><code>kubectl logs &lt;grafana-pod&gt; -n observability</code> · <code>kubectl get configmap -n observability</code> → <b>two datasource ConfigMaps, both marked default</b></td></tr>\r\n<tr><td>Root cause</td><td><b>Two datasources marked default</b> — Grafana permits exactly one; provisioning fails at startup every time → crash loop. <i>Not</i> a resource problem — a config validation failure can crash-loop a perfectly sized pod.</td></tr>\r\n<tr><td>Fix</td><td><b>Prevent:</b> install loki-stack with <code>defaultDatasourceEnabled=false</code> · <b>Repair:</b> remove <code>isDefault: true</code> from the extra ConfigMap, then <code>kubectl delete pod</code> (Deployment recreates it clean)</td></tr>\r\n<tr><td>Lesson</td><td><b>Read the crash logs</b> — the error names the subsystem (provisioning), which points straight at ConfigMaps. <b>This is the star interview story.</b></td></tr>\r\n</table></div>\r\n</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 20 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-10\">Prev</a> · <a href=\"#ch-11b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 11·b · Playbook 2/2</div><h1 id=\"scenarios-4-5-cleanup\">🛠️ Scenarios 4–5 <span class=\"en\">+ Cleanup</span></h1></div><span class=\"hmeta\">🟠 6 MIN</span></div></div>\r\n<div class=\"zone\">\r\n<p>🔴 Scenario 4 — \"Connection refused\" from Windows / WSL</p>\r\n<div class=\"table-scroll\"><table>\r\n<tr><td>Symptom</td><td>Browser on Windows can't reach <code>localhost:3000</code> even though port-forward is running</td></tr>\r\n<tr><td>Root cause</td><td>The forward was bound to loopback <b>inside the WSL VM only</b> — the <code>--address 0.0.0.0</code> flag was missing</td></tr>\r\n<tr><td>Fix</td><td><span class=\"stbad st-ok\">RE-RUN FULL COMMAND</span> <code>kubectl port-forward --address 0.0.0.0 -n observability svc/kube-prometheus-stack-grafana 3000:80</code></td></tr>\r\n<tr><td>Lesson</td><td>On WSL, your browser and your cluster live on <b>different network boundaries</b> — bind all interfaces so the port relay works</td></tr>\r\n</table></div>\r\n</div>\r\n<div class=\"zone\">\r\n<p>🟠 Scenario 5 — \"Grafana shows no data\" (general reasoning flow)</p>\r\n<p>Work the chain <b>in order</b> — the boring causes are the common ones:</p>\r\n<ol>\r\n<li><b>Is the backend pod running?</b> → <code>kubectl get pods -n observability</code> (a crashed Loki or Prometheus means no queries can succeed).</li>\r\n<li><b>Is the datasource alive?</b> → Explore → run <code>up</code> (Prometheus) or <code>{namespace=\"observability\"}</code> (Loki). If <i>Explore</i> works but a dashboard doesn't, the problem is the dashboard's query/time-range — not the stack.</li>\r\n<li><b>Missing app metrics specifically?</b> → no <code>/metrics</code> endpoint, or the ServiceMonitor selector doesn't match — check <code>up</code> for the target.</li>\r\n<li><b>Right namespace? Right time range?</b> → always worth a glance.</li>\r\n</ol>\r\n</div>\r\n<h3 id=\"ch-12\"><span class=\"n\">12</span>Cleanup — removing the entire stack</h3>\r\n<div class=\"code mini\">helm uninstall kube-prometheus-stack -n observability\r\nhelm uninstall loki-stack            -n observability\r\nkubectl delete namespace observability</div>\r\n<div class=\"mark m-warn\"><span class=\"tag\">⚠ PRACTICAL NOTE</span>Deleting the namespace removes anything the charts left behind <i>inside it</i> — but the <b>CRDs that <code>kube-prometheus-stack</code> installed are cluster-scoped</b> and may remain after uninstall. Delete them explicitly if you want a spotless cluster.</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 EXAM</span>WSL port-forward needs <code>--address 0.0.0.0</code> · \"No data\" chain: <b>backend pod → datasource (Explore) → app target → namespace/time-range</b> · Cleanup: <b>two helm uninstalls + delete namespace</b> (+ cluster-scoped CRDs by hand).</div>\r\n<p>⏭️ Now zoom out — the whole system on one page: → <a href=\"#ch-13\">Part 13: The Mental Model</a></p>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 21 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-11\">Prev</a> · <a href=\"#ch-13\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 13</div><h1 id=\"the-mental-model-architecture-on-one-page\">🗺️ The Mental Model <span class=\"en\">— Architecture on One Page</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n<div class=\"tree\"> <b>YOUR HOST</b>  (Windows / WSL)\r\n ┌──────────────────────────────────────────────────────────────┐\r\n │  Browser ──► http://localhost:3000        (admin/admin123)   │\r\n │      ▲                                                       │\r\n │      └── kubectl port-forward --address 0.0.0.0              │\r\n │            -n observability \\                                │\r\n │            svc/kube-prometheus-stack-grafana 3000:80         │\r\n └──────────────────────────┬───────────────────────────────────┘\r\n                            │  tunnel into the cluster\r\n━━━━━━━━━━━━━━━━━━━ <b>MINIKUBE CLUSTER</b> ━━━━━━━━━━━━━━━━━━━━━━━━\r\n      namespace: <u>observability</u>\r\n ┌────────────────────────────────────────────────────────────┐\r\n │                 <b>GRAFANA</b>  (Deployment)                    │\r\n │       the single UI — it stores NO data itself             │\r\n │     ▲ queries PromQL             ▲ queries LogQL           │\r\n └─────┼────────────────────────────┼──────────────────────────┘\r\n       │                            │\r\n ┌─────┴──────────────┐   ┌─────────┴────────────┐\r\n │    <b>PROMETHEUS</b>    │   │        <b>LOKI</b>         │\r\n │  pull model · TSDB │   │ label index + chunks │\r\n │ time series store  │   │ store (disk/object)  │\r\n └────────▲───────────┘   └──────────▲───────────┘\r\n          │ PULL /metrics            │ PUSH (HTTP, batched)\r\n          │                inside Loki:\r\n          │     <i>Promtail → Distributor → Ingester → Store</i>\r\n          │           (<i>Querier</i> serves Grafana's LogQL)\r\n ┌────────┴──────────────────────────────────────────────────┐\r\n │              <b>EVERY NODE</b>   (DaemonSets)                 │\r\n │  ┌───────────────┐        ┌────────────────────────┐      │\r\n │  │<b>node-exporter</b>│        │       <b>Promtail</b>       │      │\r\n │  │ host metrics: │        │ tails /var/log/pods,   │      │\r\n │  │ cpu/mem/disk/ │        │ attaches labels        │      │\r\n │  │ net           │        │ (ns/pod/ctr/node),     │      │\r\n │  └───────────────┘        │ ships to Distributor   │      │\r\n │                           └────────────────────────┘      │\r\n └───────────────────────────────────────────────────────────┘\r\n ALSO FEEDING PROMETHEUS:\r\n  • <i>kube-state-metrics</i> ── watches K8s API ──► pod status/replicas/restarts\r\n  • <i>cAdvisor</i> (inside kubelet) ────────► per-container cpu/mem usage\r\n  • <i>your apps</i> ── /metrics ─(ServiceMonitor CRD)─► auto-discovered</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🧠 THE ONE-PARAGRAPH MENTAL MODEL</span>Nodes produce raw signals. <b>Promtail pushes logs</b> into Loki, which indexes <i>only labels</i> and compresses chunks into storage. <b>Prometheus pulls metrics</b> from node-exporter, cAdvisor, kube-state-metrics, and any app with a <code>/metrics</code> endpoint + ServiceMonitor. Both systems speak the <b>same label language</b> (namespace/pod/container/node). <b>Grafana stores nothing</b> — it queries both backends live (PromQL/LogQL) and renders them for humans. You reach Grafana from your laptop through a <b>port-forward</b> because its ClusterIP isn't externally reachable.</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 22 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-11b\">Prev</a> · <a href=\"#ch-13b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 13·b</div><h1 id=\"quick-revision-the-terms-table\">📇 Quick Revision <span class=\"en\">— The Terms Table</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n<p>Every term in this book, one line each. If you can define all of these without looking — you're ready.</p>\r\n<div class=\"grid2\">\r\n<div>\r\n<div class=\"taskhead\">TASK [Signals + Logs]</div>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Term</th><th>One-line definition</th></tr>\r\n<tr><td><b>Observability</b></td><td>Understanding system state from its own data — <b>without shipping new code</b> to ask a new question</td></tr>\r\n<tr><td><b>Log</b></td><td>Discrete, timestamped event record — \"what happened, and what did it say\"</td></tr>\r\n<tr><td><b>Metric</b></td><td>Numeric measurement over time — \"how much, how fast, how often\"</td></tr>\r\n<tr><td><b>Trace</b></td><td>Full journey of one request across services — \"where did the time go\"</td></tr>\r\n<tr><td><b>Visualization</b></td><td>Dashboards turning raw signals into something a human can act on</td></tr>\r\n<tr><td><b>Loki</b></td><td>Log aggregation backend; indexes <b>labels only</b>, stores compressed chunks</td></tr>\r\n<tr><td><b>Promtail</b></td><td>DaemonSet tailing <code>/var/log/pods</code> on every node; pushes to Loki</td></tr>\r\n<tr><td><b>Distributor</b></td><td>Validates &amp; hashes incoming log streams</td></tr>\r\n<tr><td><b>Ingester</b></td><td>Batches streams into chunks and writes them</td></tr>\r\n<tr><td><b>Store</b></td><td>Keeps chunks + index (object storage or disk)</td></tr>\r\n<tr><td><b>Querier</b></td><td>Executes LogQL queries coming from Grafana</td></tr>\r\n<tr><td><b>Log Stream</b></td><td>A unique combination of labels — every distinct label set is its own stream</td></tr>\r\n<tr><td><b>LogQL</b></td><td>Loki's query language: stream selector → line filters → metric wrapper</td></tr>\r\n<tr><td><b>Chunk</b></td><td>Compressed batch of log lines in object storage / disk</td></tr>\r\n</table></div>\r\n</div>\r\n<div>\r\n<div class=\"taskhead\">TASK [Metrics · Viz · Deploy]</div>\r\n<div class=\"table-scroll\"><table>\r\n<tr><th>Term</th><th>One-line definition</th></tr>\r\n<tr><td><b>Prometheus</b></td><td>Pull-based metrics backend storing time series</td></tr>\r\n<tr><td><b>Pull Model</b></td><td>Prometheus scrapes targets on an interval; dead target = <code>up 0</code></td></tr>\r\n<tr><td><b>Time Series</b></td><td>Metric name + key/value labels + timestamped values</td></tr>\r\n<tr><td><b>PromQL</b></td><td>Prometheus query language — aggregation, filtering, rates</td></tr>\r\n<tr><td><b>Alertmanager</b></td><td>Routes PromQL alert conditions to Slack/email/PagerDuty <i>(disabled here)</i></td></tr>\r\n<tr><td><b>node-exporter</b></td><td>DaemonSet exposing host-level metrics — the <b>machine</b> layer</td></tr>\r\n<tr><td><b>kube-state-metrics</b></td><td>Watches the K8s API — object state: replicas, restarts</td></tr>\r\n<tr><td><b>cAdvisor</b></td><td>Built into the kubelet — per-container CPU/memory usage</td></tr>\r\n<tr><td><b>ServiceMonitor</b></td><td>CRD declaring which Services/Pods Prometheus scrapes</td></tr>\r\n<tr><td><b>Grafana</b></td><td>Unified UI; stores nothing — queries data sources live</td></tr>\r\n<tr><td><b>Data Source</b></td><td>URL + auth + query language (PromQL or LogQL) in Grafana</td></tr>\r\n<tr><td><b>Dashboard / Panel</b></td><td>A dashboard is a collection of panels; each renders one query</td></tr>\r\n<tr><td><b>Helm</b></td><td>K8s package manager: charts → releases from repositories</td></tr>\r\n<tr><td><b>DaemonSet</b></td><td>One pod per node — for node-local collectors</td></tr>\r\n<tr><td><b>port-forward</b></td><td>Tunnels a ClusterIP Service to <code>localhost</code> (<code>--address 0.0.0.0</code> on WSL)</td></tr>\r\n<tr><td><b>Pending · OOMKilled · CrashLoopBackOff</b></td><td>The three failure states: scheduling / memory limit / startup crash</td></tr>\r\n</table></div>\r\n</div>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">REVISION METHOD</span>Cover the right column with your hand, read each term, and say the definition out loud. Anything you stumble on → jump back to its chapter: terms map 1:1 to the <a href=\"#toc\">Table of Contents</a>.</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 23 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-13\">Prev</a> · <a href=\"#ch-14\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 14 · Interview Prep</div><h1 id=\"concept-questions-with-distilled-answers\">🎤 Concept Questions <span class=\"en\">— with Distilled Answers</span></h1></div><span class=\"hmeta\">🟠 10 MIN</span></div></div>\r\n<div class=\"grid2\">\r\n<div class=\"qa\"><span class=\"qn\">Q1</span> <b>What is observability?</b><br /><span class=\"ans\">Understanding what's happening inside a system from the data it produces — <b>without shipping new code to ask a new question</b>. Pillars: logs, metrics, traces, visualization.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q2</span> <b>Logs vs metrics vs traces — when each?</b><br /><span class=\"ans\">Logs = <i>what happened</i> (exact events). Metrics = <i>how much/how fast</i> (trends, alerting). Traces = <i>where the time went</i> (per hop). Debug flow: alert → trace → log.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q3</span> <b>Why is Loki 10–20× cheaper than full-text systems?</b><br /><span class=\"ans\">It indexes <b>only metadata (labels)</b>, not log text; text is searched at query time. Chunks are compressed into <b>cheap object storage</b>.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q4</span> <b>Pull vs push — Prometheus vs Promtail?</b><br /><span class=\"ans\">Prometheus <b>pulls</b> (scrapes on an interval — central cadence control; dead target visible via <code>up=0</code>). Promtail <b>pushes</b> HTTP batches to Loki's distributor.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q5</span> <b>Why are Promtail &amp; node-exporter DaemonSets?</b><br /><span class=\"ans\">Their data is <b>node-local</b>: container logs live in each node's <code>/var/log/pods</code>; host metrics are per-machine. One pod per node = full coverage.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q6</span> <b>What makes up a Prometheus time series?</b><br /><span class=\"ans\">A <b>metric name + key/value labels + a sequence of timestamped values</b>.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q7</span> <b>node-exporter vs kube-state-metrics vs cAdvisor?</b><br /><span class=\"ans\">Host-level machine metrics (DaemonSet) vs K8s <i>object state</i> from the API server (pod status, replicas, restarts) vs per-container usage built into the kubelet.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q8</span> <b>What are ServiceMonitor/PodMonitor and why?</b><br /><span class=\"ans\">CRDs that <b>declaratively</b> tell Prometheus which Services/Pods to scrape — no manual IP lists; deploying the CRD <i>is</i> the config (Helm auto-wires it).</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q10</span> <b>Why <code>helm upgrade --install</code> over <code>helm install</code>?</b><br /><span class=\"ans\"><b>Idempotency</b> — re-running <b>upgrades an existing release in place</b> instead of failing.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q11</span> <b>Why port-forward instead of NodePort/LoadBalancer?</b><br /><span class=\"ans\">Grafana is <b>ClusterIP</b> (internal only). Port-forward = zero-config lab access; NodePort/LB/Ingress expose it properly. On Windows/WSL you <b>must</b> pass <code>--address 0.0.0.0</code>.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q12</span> <b>Why drop Prometheus retention to 6h in a lab?</b><br /><span class=\"ans\">TSDB storage grows with retention; a lab needs no history — 6h saves significant disk.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q13</span> <b>How do logs and metrics link in this stack?</b><br /><span class=\"ans\"><b>Same label model</b> — Promtail attaches the exact labels Prometheus uses (namespace/pod/container/node), so a metric anomaly maps directly to that pod's log stream.</span></div>\r\n<div class=\"qa\"><span class=\"qn\">Q14</span> <b>Natural next step for this stack?</b><br /><span class=\"ans\"><b>Traces</b> — deploy Grafana Tempo (or Jaeger/Zipkin), instrument apps with OpenTelemetry — completing all three signals.</span></div>\r\n<div class=\"qa star\"><span class=\"qn\">Q9 ⭐</span> <b>Tell me about a bug you debugged in this stack.</b><br /><span class=\"ans\">Grafana <code>CrashLoopBackOff</code> with a datasource provisioning error: <b>both charts</b> provisioned a datasource marked <b>default</b>; Grafana allows exactly one. Diagnosed via pod logs + <code>kubectl get configmap</code>; fixed by <code>grafana.sidecar.datasources.defaultDatasourceEnabled=false</code> (or removing <code>isDefault: true</code>).</span></div>\r\n</div>\r\n<div class=\"m-exam\"><span class=\"tag\">🎓 INTERVIEW TIP</span>Q9 is <b>the star story</b> — it shows real debugging: read the crash log, form a hypothesis from the error's named subsystem (provisioning), verify with ConfigMaps, apply the targeted fix, and state the lesson (a config validation failure can crash-loop a perfectly sized pod).</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a> · <a href=\"../threads/#gitops-pull\">GitOps Pull Model</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 24 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-13b\">Prev</a> · <a href=\"#ch-14b\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 14·b</div><h1 id=\"command-cheat-sheet\">📌 Command Cheat Sheet</h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n<div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n<tr><th>Command</th><th>What it does / tells you</th></tr>\r\n<tr><td><code>helm repo add prometheus-community https://prometheus-community.github.io/helm-charts</code></td><td>Add chart repo</td></tr>\r\n<tr><td><code>helm repo add grafana https://grafana.github.io/helm-charts</code></td><td>Add chart repo</td></tr>\r\n<tr><td><code>helm repo update</code></td><td>Refresh repo indexes</td></tr>\r\n<tr><td><code>kubectl create namespace observability</code></td><td>Dedicated namespace for the stack</td></tr>\r\n<tr><td><code>helm upgrade --install &lt;release&gt; &lt;chart&gt; -n observability --set ...</code></td><td><b>Idempotent</b> install/upgrade</td></tr>\r\n<tr><td><code>helm list -n observability</code></td><td>Installed releases</td></tr>\r\n<tr><td><code>helm uninstall &lt;release&gt; -n observability</code></td><td>Remove a release</td></tr>\r\n<tr><td><code>kubectl get pods -n observability</code></td><td>First health check: Running / Pending / CrashLoopBackOff</td></tr>\r\n<tr><td><code>kubectl describe pod &lt;pod&gt; -n observability</code></td><td>Events: FailedScheduling, OOMKilled, restart reason</td></tr>\r\n<tr><td><code>kubectl logs &lt;pod&gt; -n observability</code></td><td>App-level errors (the provisioning error lives here)</td></tr>\r\n<tr><td><code>kubectl get configmap -n observability</code></td><td>Find datasource provisioning ConfigMaps</td></tr>\r\n<tr><td><code>kubectl top nodes</code> / <code>kubectl top pods -n observability</code></td><td>Actual CPU/memory vs requests</td></tr>\r\n<tr><td><code>kubectl delete pod &lt;pod&gt; -n observability</code></td><td>Force a clean restart (e.g., after ConfigMap fix)</td></tr>\r\n<tr><td><code>kubectl port-forward --address 0.0.0.0 -n observability svc/kube-prometheus-stack-grafana 3000:80</code></td><td>Access Grafana at <code>localhost:3000</code></td></tr>\r\n</table></div></div>\r\n<div class=\"taskhead\">TASK [Query one-liners]<span class=\"hst\">memorize these four</span></div>\r\n<div class=\"code mini\"><span class=\"p\">{namespace=\"observability\"}</span> <span class=\"g\"># Loki — live streams from the namespace</span>\r\n<span class=\"p\">up</span> <span class=\"g\"># Prometheus — 1 = scraped OK, 0 = down</span>\r\n<span class=\"c\">sum by (pod)</span> (<span class=\"c\">rate</span>(<span class=\"p\">container_cpu_usage_seconds_total</span>[<span class=\"y\">5m</span>]))            <span class=\"g\"># CPU per pod (cAdvisor)</span>\r\n<span class=\"c\">sum by (pod)</span> (<span class=\"c\">count_over_time</span>(<span class=\"p\">{namespace=\"default\"}</span> |= <span class=\"s\">\"error\"</span> [<span class=\"y\">5m</span>])) <span class=\"g\"># errors per pod (LogQL)</span></div>\r\n<div class=\"mark m-tip\"><span class=\"tag\">REMEMBER</span>Diagnostic order that never fails: <code>get pods</code> → <code>describe pod</code> → <code>logs</code> → <code>get configmap</code> → <code>top nodes/pods</code>. Every scenario in Part 11 uses some subset of exactly these five.</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 25 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-14\">Prev</a> · <a href=\"#ch-14c\">Next</a></span></div>\r\n</div>\r\n\r\n<div class=\"sheet\">\r\n<div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Part 14·c</div><h1 id=\"self-quiz-answer-key\">🧪 Self-Quiz <span class=\"en\">+ Answer Key</span></h1></div><span class=\"hmeta\">🟢 5 MIN</span></div></div>\r\n<div class=\"grid2\">\r\n<div class=\"qa\"><span class=\"qn\">1</span> Which Loki component validates and hashes incoming log streams?</div>\r\n<div class=\"qa\"><span class=\"qn\">2</span> From which path does Promtail read container logs, and as what workload type?</div>\r\n<div class=\"qa\"><span class=\"qn\">3</span> What three things make up a Prometheus time series?</div>\r\n<div class=\"qa\"><span class=\"qn\">4</span> Which component exposes per-container CPU/memory, and where does it run?</div>\r\n<div class=\"qa\"><span class=\"qn\">5</span> Why does Grafana crash-loop when two datasources are default, and what's the exact <code>--set</code> fix?</div>\r\n<div class=\"qa\"><span class=\"qn\">6</span> What does <code>up == 0</code> mean?</div>\r\n<div class=\"qa\"><span class=\"qn\">7</span> Why does Grafana itself store no data?</div>\r\n<div class=\"qa\"><span class=\"qn\">8</span> What are the three commands for full cleanup?</div>\r\n<div class=\"qa\"><span class=\"qn\">9</span> Which two community dashboard IDs cover Kubernetes logs and log volume?</div>\r\n<div class=\"qa\"><span class=\"qn\">10</span> Why must the port-forward use <code>--address 0.0.0.0</code> on Windows/WSL?</div>\r\n</div>\r\n<div class=\"taskhead\">TASK [Answer key]<span class=\"hst\">check yourself honestly</span></div>\r\n<div class=\"zone\">\r\n<ol>\r\n<li>The <b>Distributor</b> (then the Ingester batches streams into chunks; the Store keeps chunks + index).</li>\r\n<li><b><code>/var/log/pods</code></b> on its node; Promtail runs as a <b>DaemonSet</b> — one pod per node, because logs are node-local files.</li>\r\n<li><b>Metric name + key/value labels + a sequence of timestamped values.</b></li>\r\n<li><b>cAdvisor</b>, built into the <b>kubelet</b>.</li>\r\n<li>Grafana allows exactly <b>one default datasource</b>; provisioning fails at startup every restart. Fix: <code>--set grafana.sidecar.datasources.defaultDatasourceEnabled=false</code> when installing loki-stack.</li>\r\n<li>A scrape target is <b>down</b> — Prometheus couldn't scrape it (visible failure is a pull-model benefit).</li>\r\n<li>It's a <b>visualization layer</b>: it connects to data sources (Prometheus, Loki) and <b>queries them live</b>.</li>\r\n<li><code>helm uninstall kube-prometheus-stack -n observability</code> → <code>helm uninstall loki-stack -n observability</code> → <code>kubectl delete namespace observability</code>.</li>\r\n<li><b>13639</b> (Kubernetes Logs) and <b>12611</b> (Log volume), imported via the Grafana UI.</li>\r\n<li>Without it, the forward binds to loopback inside WSL only, and the Windows browser gets <b>connection refused</b>; <code>0.0.0.0</code> binds all host interfaces.</li>\r\n</ol>\r\n</div>\r\n<div class=\"mark m-key\"><span class=\"tag\">FINAL CHECK</span>If you can redraw the Part 13 architecture diagram from memory, define every term in Part 13·b without looking, answer all 14 interview questions out loud, and run the deployment from the cheat sheet — <b>you own this stack.</b> The route ends here. ▶</div>\r\n<div class=\"trav\"><span>Threads: </span><a href=\"../threads/#signals-slos\">Signals &amp; SLOs</a></div><div class=\"folio\"><span>📘 Observability Study Guide · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 26 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#ch-14b\">Prev</a> · <a href=\"#toc\">▲ Top</a></span></div>\r\n</div>\r\n\r\n","toc":[{"id":"observabilitystudy-guide","text":"ObservabilityStudy Guide","level":1},{"id":"table-of-contents","text":"📖 Table of Contents","level":1},{"id":"the-map-the-whole-route","text":"🗺️ The Map — The Whole Route","level":1},{"id":"what-is-observability-the-four-pillars","text":"👁️ What is Observability? — The Four Pillars","level":1},{"id":"logs-vs-metrics-vs-traces","text":"⚖️ Logs vs Metrics vs Traces","level":1},{"id":"the-core-stack-at-a-glance","text":"🧱 The Core Stack — At a Glance","level":1},{"id":"why-loki-the-philosophy-amp-the-differences","text":"📜 Why Loki? — The Philosophy &amp; the Differences","level":1},{"id":"loki-architecture-write-path-amp-read-path","text":"🏗️ Loki Architecture — Write Path &amp; Read Path","level":1},{"id":"3-athe-five-stage-pipeline","text":"3-AThe five-stage pipeline","level":3},{"id":"promtail-workflow-why-a-daemonset-the-4-steps","text":"🚚 Promtail Workflow — Why a DaemonSet + the 4 Steps","level":1},{"id":"prometheus-fundamentals","text":"📈 Prometheus — Fundamentals","level":1},{"id":"metric-sources-know-who-exposes-what","text":"🛰️ Metric Sources — Know Who Exposes What","level":1},{"id":"traces-the-journey-of-a-request","text":"🔗 Traces — The Journey of a Request","level":1},{"id":"5-1the-purpose","text":"5.1The purpose","level":3},{"id":"5-2the-tools","text":"5.2The tools","level":3},{"id":"grafana-the-unified-ui","text":"📊 Grafana — The Unified UI","level":1},{"id":"how-it-all-fits-together-in-kubernetes","text":"🧩 How It All Fits Together — in Kubernetes","level":1},{"id":"helm-kube-prometheus-stack","text":"🚀 Helm + kube-prometheus-stack","level":1},{"id":"loki-stack-the-gotcha-port-forward","text":"⚠️ loki-stack + The Gotcha + Port-Forward","level":1},{"id":"logql-querying-loki","text":"🔍 LogQL — Querying Loki","level":1},{"id":"promql-querying-prometheus","text":"📈 PromQL — Querying Prometheus","level":1},{"id":"application-integration","text":"🔌 Application Integration","level":1},{"id":"troubleshooting-playbook-scenarios-1-3","text":"🛠️ Troubleshooting Playbook — Scenarios 1–3","level":1},{"id":"scenarios-4-5-cleanup","text":"🛠️ Scenarios 4–5 + Cleanup","level":1},{"id":"12cleanup-removing-the-entire-stack","text":"12Cleanup — removing the entire stack","level":3},{"id":"the-mental-model-architecture-on-one-page","text":"🗺️ The Mental Model — Architecture on One Page","level":1},{"id":"quick-revision-the-terms-table","text":"📇 Quick Revision — The Terms Table","level":1},{"id":"concept-questions-with-distilled-answers","text":"🎤 Concept Questions — with Distilled Answers","level":1},{"id":"command-cheat-sheet","text":"📌 Command Cheat Sheet","level":1},{"id":"self-quiz-answer-key","text":"🧪 Self-Quiz + Answer Key","level":1}],"words":8885,"assets":[]};